    @Test("starts the daemon and not the command-line tool") func h381ServiceDaemon() { let s = BackendServersHostScripts.service("/home/me/.local/bin/terminaldeck"); for part in ["ExecStart=$host", #"host="$rt/bin/terminaldeck-host""#, #"host="$bin/terminaldeck-host""#, "grep -q terminaldeck-launcher"] { #expect(s.contains(part)) } }
