    @Test("reports every step, in order, and ends linked to this computer") func h630InstallSteps() async { let f = BackendServersHostPortBox(), h = BackendServersHosts(f.dependencies); let result = await f.install(h); #expect(f.states.values.map(\.step) == [.checking, .uploading, .installing, .service, .pairing, .pairing, .done]); #expect(f.states.values.map(\.line).contains("Approved. Waiting for this computer to reach it.")); #expect(result.line.contains("linked to this computer") && result.done.count == 5); #expect(result.done[1].contains("Copied the package to") && result.done[3].contains("keeps running when you log out") && result.done[4].contains("linked to this computer as office-pc")) }
    @Test("waits for the channel to come up before saying it is linked") func h666ExactMachineWait() async { var o = BackendServersHostPortOptions(); o.reaches = true; let f = BackendServersHostPortBox(o); let r = await f.install(BackendServersHosts(f.dependencies)); #expect(r.step == .done && r.line == "It is running, and linked to this computer." && r.detail == ""); #expect(f.waited.values == [BackendServersHostPortFixtures.machine]) }
    @Test("says the channel never came up rather than claiming a link") func h684NoChannel() async { var o = BackendServersHostPortOptions(); o.reaches = false; let f = BackendServersHostPortBox(o); let r = await f.install(BackendServersHosts(f.dependencies)); #expect(r.step == .done && r.line.contains("has not reached it yet") && r.detail.contains("Link this computer")); #expect(r.done.contains { $0.contains("approved as your own device") }) }
