    @Test("waits for the host to reach the relay before asking it for a code") func h771RelayReadinessEvent() async { let entered = BackendServersSetupPortSignal(), ready = BackendServersSetupPortSignal(); var o = BackendServersHostPortOptions(); o.beforeProbe = { at in if at == 1 { entered.send(); await ready.wait() } }; let f = BackendServersHostPortBox(o); let h = BackendServersHosts(f.dependencies); let operation = Task { await f.install(h) }; await entered.wait(); #expect(f.redeemed.values.isEmpty && !f.shell.writes.contains { $0.contains("pair --kind") }); ready.send(); let r = await operation.value; #expect(r.step == .done && r.line.contains("linked to this computer") && f.redeemed.values == ["904021"]) }
    @Test("asks for a code anyway when the relay never comes up") func h784RelayCourtesyCeiling() async { var o = BackendServersHostPortOptions(); o.after = BackendServersHostPortFixtures.offRelay; o.codes = ["904021", "111111", "222222"]; o.answers = [.refused("Nothing answered for that code at the relay.")]; let f = BackendServersHostPortBox(o); let r = await f.install(BackendServersHosts(f.dependencies)); #expect(f.redeemed.values == o.codes && r.detail.contains("nothing at the relay to answer")) }
