    private func address() throws -> String { try #require(BackendSharedServerAddresses.format(url: "wss://relay.terminaldeck.dev", hostId: BackendServersHostPortFixtures.machine, hostKey: BackendSharedServerAddresses.toBase64Url(Data(repeating: 7, count: 32)))) }
